# BUG 1: Wrong comparison - paper vs rock
if player == "rock" and computer == "scissors":
    return "player"
elif player == "paper" and computer == "scissors":  # BUG: should be rock!
    return "player"
elif player == "scissors" and computer == "paper":
    return "player"
# BUG 2: These conditions are duplicates of player wins!
elif player == "rock" and computer == "paper":
    return "player"  # BUG: Should return "computer"!
elif player == "paper" and computer == "scissors":
    return "computer"
elif player == "scissors" and computer == "rock":
    return "computer"
# BUG 3: Missing the equals case properly
else:
    return None  # BUG: Should explicitly check for tie

current_room = 0
print("=== {{school}} Adventure ===")
print(buggy_get_room_description(current_room))

while current_room != 3:  # Exit is room 3
    command = input("\n> ").lower().strip()

    if command in ["north", "south", "east", "west"]:
        new_room = buggy_move(current_room, command)
        if new_room == current_room:
            print("You can't go that way.")
        else:
            current_room = new_room
            print(buggy_get_room_description(current_room))
    elif command == "look":
        print(buggy_get_room_description(current_room))
    elif command == "quit":
        break
    else:
        print("Unknown command.")

print("\nThanks for playing!")

